<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])){header('Location: login.php');exit;} if(($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Solo el superadmin puede administrar tiendas.');} $config=require __DIR__.'/config.php'; function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');} try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$stores=$pdo->query('SELECT id,nombre,slug,eslogan,telefono_whatsapp,ciudad,modalidad,porcentaje_comision,estado,created_at FROM tiendas ORDER BY id DESC')->fetchAll();}catch(Throwable $e){http_response_code(500);exit('No se pudieron cargar las tiendas.');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tiendas</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0;color:#171717}main{max-width:1100px;margin:auto;padding:30px 20px}.card{background:#fff;padding:22px;border-radius:16px;margin:16px 0}a{color:#886c42}label{display:block;margin:9px 0 4px}input,select,textarea{box-sizing:border-box;width:100%;padding:9px;border:1px solid #ccc;border-radius:7px}button{margin-top:12px;padding:10px 15px;border:0;border-radius:7px;background:#886c42;color:#fff}table{width:100%;border-collapse:collapse;min-width:800px}th,td{padding:10px 7px;text-align:left;border-bottom:1px solid #eee}th{font-size:13px;color:#666}.table{overflow:auto}</style></head><body><main><p><a href="panel.php">← Panel</a> · <a href="logout.php">Cerrar sesión</a></p><section class="card"><h1>Administración de tiendas</h1><p>Registra las tiendas que aparecerán en la Galería Cusco.</p><form method="post" action="tienda-guardar.php"><label>Nombre</label><input name="nombre" maxlength="150" required><label>Eslogan</label><input name="eslogan" maxlength="255"><label>WhatsApp</label><input name="telefono_whatsapp" maxlength="20" required><label>Dirección</label><input name="direccion" maxlength="255"><label>Ciudad</label><input name="ciudad" value="Cusco" maxlength="100"><label>Modalidad</label><select name="modalidad"><option value="alquilada_fija">Alquilada fija</option><option value="alquilada_comision">Alquilada por comisión</option><option value="administrada">Administrada</option></select><label>Comisión (%)</label><input type="number" name="porcentaje_comision" min="0" max="100" step="0.01" value="0"><button>Registrar tienda</button></form></section><section class="card"><h2>Tiendas registradas</h2><div class="table"><table><thead><tr><th>Nombre</th><th>Enlace</th><th>Contacto</th><th>Modalidad</th><th>Comisión</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($stores as $s):?><tr><td><strong><?=h($s['nombre'])?></strong><br><small><?=h($s['eslogan']??'')?></small></td><td><a target="_blank" href="tienda.php?slug=<?=urlencode($s['slug'])?>">Ver catálogo →</a></td><td><?=h($s['telefono_whatsapp'])?><br><?=h($s['ciudad'])?></td><td><?=h($s['modalidad'])?></td><td><?=h((string)$s['porcentaje_comision'])?>%</td><td><?=h($s['estado'])?></td><td><a href="tienda-editar.php?id=<?=$s['id']?>">Editar</a></td></tr><?php endforeach; if(!$stores):?><tr><td colspan="6">No hay tiendas registradas.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>

